# Geodesic along wall distances; using scipy distance_transform? implement multi-source BFS per region
from collections import deque
def wall_geodesic(grid, wallc, compslab, sourceids, modal, output=None):
 mask=(grid==wallc); H,W=grid.shape
 dd=[]
 for sid in sourceids:
  dist=np.full((H,W),999,dtype=int); q=deque()
  # source wall cells 4adjacent to region sid
  for r,c in np.argwhere(mask):
   if any(0<=r+dr<H and 0<=c+dc<W and compslab[r+dr,c+dc]==sid for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))): dist[r,c]=1;q.append((r,c))
  while q:
   r,c=q.popleft()
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=r+dr,c+dc
