  ds=[D[r,c] for D in dd]; m=min(ds); ix=[j for j,x in enumerate(ds) if x==m]; cs={modal[sourceids[j]] for j in ix}; pr[r,c]=cs.pop() if len(cs)==1 else wallc
 return pr,np.array(dd)
